from typing import List

def solveLexicographicallySmallestSubstringOperation(input: str) -> List[str]:
    s = input.strip()
    chars = list(s)
    if all(c == 'a' for c in chars):
        chars[-1] = 'z'
        return [''.join(chars)]
    started = False
    for i in range(len(chars)):
        if chars[i] != 'a':
            chars[i] = chr(ord(chars[i]) - 1)
            started = True
        elif started:
            break
    return [''.join(chars)]

class Solution {
    String[] solveLexicographicallySmallestSubstringOperation(String input) {
        char[] chars = input.trim().toCharArray();
        boolean allA = true;
        for (char c : chars) if (c != 'a') { allA = false; break; }
        if (allA) {
            chars[chars.length - 1] = 'z';
            return new String[]{new String(chars)};
        }
        boolean started = false;
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] != 'a') {
                chars[i] = (char) (chars[i] - 1);
                started = true;
            } else if (started) break;
        }
        return new String[]{new String(chars)};
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
   public:
    vector<string> solveLexicographicallySmallestSubstringOperation(string input) {
        string s = input;
        while (!s.empty() && isspace(s.back())) s.pop_back();
        bool allA = true;
        for (char c : s)
            if (c != 'a') {
                allA = false;
                break;
            }
        if (allA) {
            if (!s.empty()) s.back() = 'z';
            return {s};
        }
        bool started = false;
        for (char& c : s) {
            if (c != 'a') {
                c--;
                started = true;
            } else if (started)
                break;
        }
        return {s};
    }
};
